 OR NEW.id<>OLD.id OR NEW.at<>OLD.at OR NEW.subject_kind<>OLD.subject_kind OR NEW.subject_revision<>OLD.subject_revision
 OR NEW.action<>OLD.action OR NEW.decision<>OLD.decision
