);
CREATE UNIQUE INDEX pt_spreadsheet_external ON pt_spreadsheet_keys(dataset, lower(external_id)) WHERE external_id <> '';
CREATE UNIQUE INDEX pt_spreadsheet_name ON pt_spreadsheet_keys(dataset, lower(name));

