 recipient TEXT NOT NULL,
 subject TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('sending','accepted','rejected','rate_limited','uncertain','suppressed','failed','cancelled')),
 provider TEXT NOT NULL DEFAULT '',
